package com.ferreteriahuaman.repository;
import com.ferreteriahuaman.dto.InventoryModels.*;
import com.ferreteriahuaman.dto.CatalogModels.Page;
import java.math.BigDecimal;import java.sql.*;import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
@Repository @Profile("db")
public class InventoryRepository {
 private final JdbcTemplate jdbc;public InventoryRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private Map<String,Object> row(ResultSet r,int n)throws SQLException{var map=new LinkedHashMap<String,Object>();var meta=r.getMetaData();for(int i=1;i<=meta.getColumnCount();i++){Object value=r.getObject(i);if(value instanceof BigDecimal b)value=b.toPlainString();else if(value instanceof Timestamp t)value=t.toLocalDateTime().toString();map.put(meta.getColumnLabel(i),value);}return map;}
 private String pattern(String value){String e=Character.toString(92);return "%"+value.replace(e,e+e).replace("%",e+"%").replace("_",e+"_")+"%";}
 private Page<Map<String,Object>> page(String select,String from,String filter,String order,List<Object> args,int page,int size){long total=jdbc.queryForObject("select count(*) "+from+filter,Long.class,args.toArray());var params=new ArrayList<>(args);params.add(size);params.add((long)page*size);return new Page<>(jdbc.query(select+from+filter+order+" limit ? offset ?",this::row,params.toArray()),total,page,size);}
 public Page<Map<String,Object>> alerts(String q,String state,int page,int size){return page("select a.id_alerta id,p.id_producto \"productoId\",p.codigo,p.nombre producto,u.abreviatura unidad,p.stock_actual::text \"stockActual\",p.stock_minimo::text \"stockMinimo\",a.stock_al_generar::text \"stockAlGenerar\",a.estado_alerta estado,a.feccre fecha,a.fecha_cierre \"fechaCierre\" ","from huaman.alerta_stock a join huaman.producto p using(id_producto) join huaman.unidad_medida u on u.id_unidad=p.id_unidad ","where a.estado='A' and (p.nombre ilike ? or p.codigo ilike ?) and (?='' or a.estado_alerta=?)"," order by a.id_alerta desc",List.of(pattern(q),pattern(q),state,state),page,size);}
 public Page<Map<String,Object>> adjustments(String q,String type,int page,int size,boolean costs){return page("select a.id_ajuste id,a.numero,p.codigo,p.nombre producto,a.id_producto \"productoId\",u.abreviatura unidad,a.tipo_ajuste tipo,a.cantidad::text cantidad,m.nombre motivo,a.observacion,a.feccre fecha,"+(costs?"a.costo_unitario_base::text":"null::text")+" \"costoUnitarioBase\" ","from huaman.ajuste_inventario a join huaman.producto p using(id_producto) join huaman.unidad_medida u on u.id_unidad=p.id_unidad join huaman.motivo_ajuste m using(id_motivo_ajuste) ","where a.estado='A' and (p.nombre ilike ? or p.codigo ilike ?) and (?='' or a.tipo_ajuste=?)"," order by a.id_ajuste desc",List.of(pattern(q),pattern(q),type,type),page,size);}
 public List<Map<String,Object>> reasons(){return jdbc.query("select id_motivo_ajuste id,nombre from huaman.motivo_ajuste where estado='A' order by nombre",this::row);}
 private static final String TAKE_SELECT="select t.id_toma id,t.numero,t.alcance,t.id_categoria \"categoriaId\",c.nombre categoria,t.fecha_inicio fecha,t.estado_toma estado,t.revision,t.observacion,(select count(*) from huaman.detalle_toma_inventario l where l.id_toma=t.id_toma and l.estado='A') productos,(select count(*) from huaman.detalle_toma_inventario l where l.id_toma=t.id_toma and l.estado='A' and l.estado_linea='CONTADA') contados ";
 private static final String TAKE_FROM="from huaman.toma_inventario t left join huaman.categoria c using(id_categoria) ";
 public Page<Map<String,Object>> takes(String q,String state,int page,int size){return page(TAKE_SELECT,TAKE_FROM,"where t.estado='A' and (t.numero::text ilike ? or coalesce(c.nombre,'Todo el almacén') ilike ?) and (?='' or t.estado_toma=?)"," order by t.id_toma desc",List.of(pattern(q),pattern(q),state,state),page,size);}
 public Optional<Map<String,Object>> take(long id){return jdbc.query(TAKE_SELECT+TAKE_FROM+"where t.id_toma=? and t.estado='A'",this::row,id).stream().findFirst();}
 public Page<Map<String,Object>> counts(long id,String q,int page,int size,boolean costs){String plan="coalesce((select jsonb_agg(jsonb_build_object('unidadId',v->'id_unidad','condicion',v->'condicion','presentacionId',v->'id_presentacion','cantidad',v->>'cantidad')) from jsonb_array_elements(d.unidades_contadas) v),'[]'::jsonb)::text";return page("select d.id_detalle_toma id,d.id_producto \"productoId\",p.nombre producto,p.codigo,p.modo_control \"modoControl\",u.abreviatura unidad,d.stock_sistema::text \"stockSistema\",d.cantidad_contada::text cantidad,d.diferencia::text diferencia,d.estado_linea estado,d.revision,"+plan+" plan,"+(costs?"d.costo_referencia::text":"null::text")+" \"costoReferencia\" ","from huaman.detalle_toma_inventario d join huaman.producto p using(id_producto) join huaman.unidad_medida u on u.id_unidad=p.id_unidad ","where d.id_toma=? and d.estado='A' and (p.nombre ilike ? or p.codigo ilike ?)"," order by p.nombre,d.id_producto",List.of(id,pattern(q),pattern(q)),page,size);}
 public long adjust(Adjustment i,String units){return jdbc.queryForObject("select huaman.registrar_ajuste(?,?,?,?,?,?,?::jsonb)",Long.class,i.productoId(),i.tipo(),i.cantidad(),i.motivoId(),i.observacion(),i.clave(),units);}
 public long transform(Transformation i,String lengths){return i.operacion().equals("ABRIR")?jdbc.queryForObject("select huaman.abrir_envase(?,?,?)",Long.class,i.origenId(),i.clave(),i.motivo()):jdbc.queryForObject("select huaman.cortar_tramo(?,?::jsonb,?,?)",Long.class,i.origenId(),lengths,i.clave(),i.motivo());}
 public long start(Start i){return jdbc.queryForObject("select huaman.iniciar_toma(?,?,?,?)",Long.class,i.alcance(),i.categoriaId(),i.clave(),i.observacion());}
 public long count(long id,Count i,String units){return jdbc.queryForObject("select huaman.guardar_conteo(?,?,?,?,?,?::jsonb)",Long.class,id,i.productoId(),i.cantidad(),i.revision(),i.clave(),units);}
 public long transition(long id,String action,Transition i){String function=switch(action){case "cerrar"->"cerrar_toma";case "reabrir"->"reabrir_toma";case "anular"->"anular_toma";case "aprobar"->"aprobar_toma";default->throw new IllegalArgumentException();};return action.equals("cerrar")?jdbc.queryForObject("select huaman."+function+"(?,?,?)",Long.class,id,i.revision(),i.clave()):jdbc.queryForObject("select huaman."+function+"(?,?,?,?)",Long.class,id,i.revision(),i.clave(),i.motivo());}
}
